INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Apa ciri utama yang membedakan makhluk hidup dari benda mati?','','["Hanya bergerak","Dapat bernapas, tumbuh, dan berkembang biak","Memiliki warna yang cerah","Selalu keras dan padat"]',1,'Makhluk hidup memiliki tiga ciri paling penting: bernapas, tumbuh, dan berkembang biak.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Burung merpati, elang, dan ayam sama-sama masuk dalam klasifikasi apa?','','["Mamalia","Burung","Serangga","Reptil"]',1,'Ciri burung adalah memiliki bulu, bertelur, dan memiliki sayap.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Hewan apa yang masuk dalam kategori mamalia?','','["Ular, buaya, tokek","Kucing, sapi, lumba-lumba","Katak, salamander, cecak","Nila, lele, ikan hiu"]',1,'Mamalia adalah hewan yang memiliki rambut dan menyusui anaknya.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Apa nama proses yang dilakukan tumbuhan untuk membuat makanannya sendiri menggunakan cahaya matahari?','','["Respirasi","Fotosintesis","Pencernaan","Transpirasi"]',1,'Kata ''foto'' berarti cahaya, ''sintesis'' berarti menyusun — proses ini butuh cahaya matahari.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Seekor burung elang memiliki paruh yang kuat dan tajam. Adaptasi ini berguna untuk apa?','','["Untuk bernyanyi lebih nyaring","Untuk mencengkeram dan mencabik mangsa","Untuk membantu penerbangan lebih cepat","Untuk minum air lebih banyak"]',1,'Elang adalah burung pemangsa, dan paruhnya dirancang khusus untuk mengambil daging.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Ikan hidup di air dan memiliki alat khusus untuk bergerak dan menjaga keseimbangan. Alat apa itu?','','["Paru-paru","Sayap","Sirip","Kaki"]',2,'Ikan berenang menggunakan bagian tubuh yang pipih dan mengepak-ngepak di dalam air.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Tiga kebutuhan dasar apa saja yang harus dipenuhi oleh semua makhluk hidup?','','["Makanan, air, dan udara","Rumah, mainan, dan teman","Cahaya, garam, dan logam","Listrik, internet, dan buku"]',0,'Semua makhluk hidup — dari mikroba hingga gajah — butuh ketiga hal ini untuk hidup.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Bagian tumbuhan apa yang berfungsi menyerap air dan nutrisi dari tanah?','','["Akar","Batang","Daun","Bunga"]',0,'Bagian tumbuhan yang tertanam dalam tanah dan tidak kelihatan dari atas adalah ...','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Daun berfungsi untuk fotosintesis. Selain itu, daun juga mengeluarkan zat apa melalui pori-porinya?','','["Air dan oksigen (O₂)","Tanah dan batu","Cahaya dan panas","Akar dan benih"]',0,'Proses pengeluaran air melalui daun disebut transpirasi; sementara gas yang dilepas dari fotosintesis adalah oksigen.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Katak dimulai hidupnya dari telur kecil, kemudian menjadi berudu dengan ekor, lalu akhirnya menjadi katak dewasa. Fase hidup seperti ini disebut apa?','','["Adaptasi","Metamorfosis","Fotosintesis","Germinasi"]',1,'Kata ''meta'' berarti perubahan, ''morph'' berarti bentuk — perubahan bentuk yang besar.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Manakah dari hewan berikut yang termasuk reptil?','','["Lumba-lumba","Buaya","Burung hantu","Kelelawar"]',1,'Reptil memiliki kulit bersisik, berdarah dingin, dan sebagian besar bertelur.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Apa perbedaan utama antara amfibi dan reptil?','','["Amfibi memiliki bulu, reptil tidak","Amfibi membutuhkan air untuk berkembang biak, reptil bertelur di darat","Amfibi tidak bertelur, reptil bertelur","Reptil memiliki sayap, amfibi tidak"]',1,'Amfibi berarti ''dua kehidupan'' — mereka perlu air untuk bertelur dan masa mudanya.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Serangga apa yang mengalami metamorfosis lengkap dengan urutan telur → larva → pupa → dewasa?','','["Belalang","Kupu-kupu","Jangkrik","Capung"]',1,'Hewan ini dimulai dari telur, menjadi ulat, lalu masuk kepompong, dan akhirnya bersayap indah.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Tanaman X memiliki bunga berwarna merah cerah dan aroma yang wangi. Tujuan utama bunga pada tumbuhan adalah untuk ...','','["Menghiasi pekarangan","Menarik serangga untuk penyerbukan","Menyimpan air","Memproduksi akar baru"]',1,'Warna cerah dan aroma wangi adalah ''undangan'' untuk serangga agar datang.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Urutan klasifikasi makhluk hidup dari kelompok terbesar ke terkecil yang benar adalah ...','','["Kingdom → Filum → Kelas → Ordo → Famili → Genus → Spesies","Spesies → Genus → Famili → Ordo → Kelas → Filum → Kingdom","Filum → Kingdom → Kelas → Ordo → Famili → Genus → Spesies","Kingdom → Filum → Genus → Kelas → Ordo → Famili → Spesies"]',0,'Kingdom adalah kelompok terbesar (paling umum), Spesies adalah yang terkecil (paling spesifik).','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Tumbuhan A memiliki daun kecil, batang berduri, dan akar yang sangat panjang. Tumbuhan ini paling cocok hidup di mana?','','["Hutan hujan yang basah","Gunung yang dingin","Padang pasir yang kering","Pantai dengan air asin"]',2,'Daun kecil dan akar panjang adalah adaptasi untuk menghemat air di tempat yang sangat kering.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Jika sebuah tanaman hanya mendapat cahaya matahari 2 jam per hari, apa yang akan terjadi pada fotosintesisnya?','','["Fotosintesis akan lebih cepat","Fotosintesis akan berkurang karena cahaya kurang","Fotosintesis akan sama seperti biasanya","Tanaman tidak akan melakukan fotosintesis sama sekali"]',1,'Fotosintesis membutuhkan cahaya matahari — kurang cahaya berarti berkurang proses ini.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Urutan siklus hidup kupu-kupu yang benar adalah ...','','["Telur → Ulat → Kepompong → Kupu-kupu","Ulat → Telur → Kupu-kupu → Kepompong","Kepompong → Telur → Ulat → Kupu-kupu","Kupu-kupu → Kepompong → Telur → Ulat"]',0,'Kupu-kupu ibu bertelur, telurnya menetas jadi ulat, ulat berubah di kepompong, lalu keluar jadi kupu-kupu.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Hewan-hewan ini adalah mamalia, KECUALI ...','','["Paus dan lumba-lumba","Tikus dan tupai","Buaya dan ular","Orangutan dan gorila"]',2,'Buaya dan ular adalah reptil, bukan mamalia — mereka tidak menyusui anaknya.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_1','Batang tumbuhan berfungsi mengalirkan air dan nutrisi dari akar ke daun. Pembuluh yang mengangkut air ke atas disebut ...','','["Floem","Xilem","Stomata","Klorofil"]',1,'Pembuluh kayu (xilem) mengangkut air ke atas; pembuluh tapis (floem) mengangkut hasil fotosintesis ke bawah.','hard','');
