INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Apa perbedaan utama antara metamorfosis sempurna dan metamorfosis tidak sempurna?','','["Sempurna punya 3 tahap, tidak sempurna punya 4 tahap","Sempurna punya telur-larva-pupa-dewasa, tidak sempurna punya telur-nimfa-dewasa","Tidak sempurna terjadi di air, sempurna terjadi di darat","Sempurna lebih cepat selesai daripada tidak sempurna"]',1,'Ingat: tahap pupa (perubahan besar) hanya ada di metamorfosis sempurna.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Contoh serangga yang mengalami metamorfosis sempurna adalah...','🦋 vs 🦗','["Belalang dan jangkrik","Kupu-kupu dan lebah","Walang sangit dan tonggeret","Kecoa dan kepinding"]',1,'Ingat: kupu-kupu pasti melewati tahap kepompong (pupa).','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Di mana posisi produsen dalam rantai makanan ekosistem?','','["Di awal rantai makanan, berfungsi membuat energi dari matahari","Di tengah rantai makanan, memakan produsen","Di akhir rantai makanan, memakan semua konsumen","Tidak ada posisi tetap dalam rantai makanan"]',0,'Produsen adalah yang bisa membuat makanan sendiri dari cahaya matahari.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Peran pengurai dalam ekosistem adalah...','🦠🍂','["Membuat energi dari matahari seperti tumbuhan","Memecah sisa-sisa makhluk mati menjadi nutrisi tanah","Memakan semua konsumen tingkat satu","Menghasilkan oksigen untuk ekosistem"]',1,'Pengurai termasuk bakteri dan jamur yang membuat tanah subur.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Serangga apa yang berperan sebagai predator alami hama dan sangat membantu petani?','🐛🌾','["Nyamuk","Lalat buah","Belalang","Kepik"]',3,'Serangga ini memakan serangga hama yang merusak tanaman padi dan sayuran.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Mengapa keseimbangan ekosistem penting dijaga?','','["Agar semua makhluk hidup bisa bertahan dalam jumlah seimbang","Agar tanah selalu subur sepanjang tahun","Agar musim tidak berubah-ubah","Agar hewan besar tidak punah"]',0,'Jika salah satu makhluk berkurang atau bertambah banyak, rantai makanan jadi berantakan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Manakah urutan tahap metamorfosis sempurna pada kupu-kupu yang BENAR?','🥚 → ? → ? → 🦋','["Telur → Larva → Kepompong → Kupu-kupu dewasa","Telur → Kepompong → Larva → Kupu-kupu dewasa","Telur → Kupu-kupu muda → Kepompong → Kupu-kupu dewasa","Kepompong → Telur → Larva → Kupu-kupu dewasa"]',0,'Larva makan daun banyak-banyakan sebelum jadi kepompong.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Dalam jaring makanan, satu serangga herbivora bisa dimakan oleh berapa jenis pemangsa?','🦗 ← ? pemangsa','["Hanya 1 jenis pemangsa saja","Paling banyak 2 jenis pemangsa","Bisa lebih dari 1 jenis pemangsa (bisa 2, 3, atau lebih)","Tidak ada pemangsa khusus untuk serangga herbivora"]',2,'Jaring makanan lebih kompleks daripada rantai makanan lurus, karena ada banyak pilihan makanan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Habitat serangga air seperti larva nyamuk dan larva capung adalah...','🪴💧','["Sarang serangga yang kering","Pohon tinggi dengan daun tebal","Kolam, rawa, atau tanah lembab","Batu karang di tepi pantai"]',2,'Larva nyamuk harus hidup di air atau tanah sangat basah untuk bernapas melalui siphon.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Jika populasi lebah berkurang drastis, apa dampak langsungnya bagi tanaman berbunga?','🐝❌ → 🌼?','["Lebih banyak bunga mekar di musim semi","Serbuk sari tidak terpindahkan, banyak bunga tidak jadi buah","Tanaman akan berevolusi cepat untuk penyerbukan angin","Tidak ada dampak karena angin juga bisa bawa serbuk sari"]',1,'Lebah memindahkan serbuk sari ke putik bunga lain agar terjadi penyerbukan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Serangga mana yang tubuhnya berwarna menyerupai lingkungannya sehingga sulit terlihat (kamuflase)?','🦗 🎨','["Semut hitam","Belalang hijau di antara daun-daun","Kumbang badak","Kupu-kupu raja (monarch)"]',1,'Serangga ini berwarna hampir sama dengan daun atau ranting tempatnya bersembunyi.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Apa yang dimaksud dengan ''rantai makanan'' dalam ekosistem?','','["Urutan makhluk hidup yang saling memangsa mulai dari produsen hingga pemangsa puncak","Semua jenis makanan yang dimakan oleh semua hewan","Tempat di mana makanan disimpan di hutan","Hubungan antara tumbuhan dan tanah saja"]',0,'Rantai makanan menunjukkan ''siapa makan siapa'' dengan urutan dari tumbuhan ke hewan pemangsa.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Konsumen tingkat 2 dalam rantai makanan berikut adalah siapa? (Rumput → Belalang → Burung → Ular)','🌾 → 🦗 → 🐦 → 🐍','["Rumput","Belalang","Burung","Ular"]',2,'Konsumen tingkat 2 adalah yang memakan konsumen tingkat 1 (herbivora).','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Habitat ideal serangga kebanyakan adalah tempat yang...','🌳🌍','["Sangat panas (di atas 50°C) dan kering","Hangat, lembab, banyak tumbuhan, dan punya tempat persembunyian","Dingin ekstrem dan bersalju sepanjang tahun","Terbuka lebar tanpa pohon atau semak belukar"]',1,'Serangga butuh suhu sedang, kelembaban, makanan (tumbuhan/hewan lain), dan tempat bersarang.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Kapan waktu terbaik lebah keluar dari sarang untuk menyerbuki bunga?','🐝 ☀️','["Pagi atau sore hari saat cuaca cerah","Malam hari saat sejuk","Saat hujan deras","Tengah malam saat bunga menutup"]',0,'Lebah tidak terbang saat ada angin kuat atau saat gelap.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Jika dibuat daftar makhluk hidup berdasarkan rantai makanan: Rumput, Ulat, Burung, Elang — siapa yang punya energi PALING BANYAK?','⚡','["Elang","Burung","Ulat","Rumput"]',3,'Produsen menyimpan energi terbanyak dari matahari; semakin tinggi tingkat pemangsaan, energi semakin berkurang.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Serangga mana yang disebut sebagai penyerbuk bunga paling efektif di kebun buah?','🌼','["Semut","Lalat rumah","Lebah madu dan tawon","Belalang hijau"]',2,'Serangga dengan rambut halus di tubuhnya yang menempel serbuk sari adalah penyerbuk terbaik.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Berapa jumlah tahap yang HARUS dilalui serangga yang mengalami metamorfosis tidak sempurna?','📊','["1 tahap saja","2 tahap (telur dan dewasa)","3 tahap (telur, nimfa, dewasa)","4 tahap atau lebih"]',2,'Metamorfosis tidak sempurna TIDAK punya tahap pupa.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_2','Peristiwa apa yang akan terjadi jika tumbuhan (produsen) di ekosistem mendadak berkurang 50%?','🌾❌','["Hanya herbivora yang akan terpengaruh, pemangsa tidak apa-apa","Seluruh rantai makanan akan terganggu, herbivora kurang makan, pemangsa juga kurang makan","Pemangsa akan berkembang biak lebih cepat","Tidak ada dampak karena pemangsa bisa mencari makanan lain"]',1,'Gangguan di awal rantai makanan (produsen) akan merambat ke semua tingkat lainnya.','hard','');
