INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Es batu adalah air dalam wujud apa?','❄️','["Cair","Padat","Gas","Uap"]',1,'Es batu keras dan memiliki bentuk tetap.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Proses berubahnya air menjadi uap air disebut...','🌡️💨','["Membeku","Menguap","Mengembun","Menyublim"]',1,'Terjadi saat air dipanaskan, misalnya saat memasak air hingga mengepul.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Saat pagi hari, embun terbentuk di rumput. Perubahan wujud apa yang terjadi?','🌅💧','["Menguap","Membeku","Mengembun","Menyublim"]',2,'Gas air di udara berubah menjadi tetes kecil cair karena suhu dingin.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Besi memiliki sifat keras, berat, dan mengkilap. Sifat-sifat tersebut termasuk sifat...','🔩','["Kimia","Fisika","Biologis","Magnet"]',1,'Sifat ini bisa dilihat dan diukur tanpa mengubah jenis zatnya.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Manakah dari benda berikut yang merupakan penghantar panas terbaik?','🔥','["Plastik","Kayu","Aluminium","Kain"]',2,'Logam yang sering dipakai untuk wajan dan panci bisa menjadi panas dengan cepat.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Es mencair menjadi air ketika dipanaskan. Proses sebaliknya (air membeku menjadi es) memerlukan...','❄️💧','["Pemanasan","Pendinginan","Penguapan","Pengadukan"]',1,'Kebalikan dari mencair adalah proses yang menghilangkan panas dari air.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Sumber energi yang dapat diperbaharui dari alam adalah...','☀️','["Minyak bumi","Batu bara","Energi matahari","Gas alam"]',2,'Sumber yang tidak akan habis selama matahari masih bersinar.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Ketika kamu mendorong mainan mobil, gaya apa yang kamu berikan?','👉🚗','["Gaya tarik","Gaya dorong","Gaya gesek","Gaya gravitasi"]',1,'Tanganmu menggerakkan mainan itu menjauh dari dirimu.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Magnet memiliki dua kutub. Kutub yang sama akan saling...','🧲🧲','["Menarik","Menolak","Berputar","Berdekatan"]',1,'Dua kutub utara magnet tidak akan bersatu, mereka saling menghindar.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Perubahan wujud dari padat langsung menjadi gas tanpa melalui fase cair disebut...','❄️💨','["Mengembun","Menyublim","Menguap","Membeku"]',1,'Kapur barus (naftalena) lama-kelamaan menghilang tanpa meninggalkan cairan.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Gaya gesekan antara ban mobil dan jalan aspal akan menyebabkan...','🚗🛣️','["Ban menjadi halus","Ban menjadi panas","Ban menjadi lebih keras","Ban mengembang"]',1,'Saat ban bergesekan dengan jalan, energi gerak diubah menjadi panas.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Manakah yang BUKAN sumber energi?','❓','["Angin","Air terjun","Matahari","Plastik"]',3,'Salah satu pilihan adalah benda buatan manusia yang tidak menghasilkan energi sendiri.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Ketika lilin menyala, energi apa yang dihasilkan?','🕯️','["Energi listrik dan gerak","Energi panas dan cahaya","Energi angin","Energi magnet"]',1,'Lilin yang menyala memberikan nyala api dan kehangatan di sekitarnya.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Besi yang diletakkan di dekat magnet akan tertarik. Hal ini terjadi karena...','🧲⚙️','["Besi terbuat dari bahan yang sama dengan magnet","Besi memiliki sifat magnetik sehingga bisa ditarik magnet","Besi dan magnet memiliki kutub yang sama","Besi lebih berat dari magnet"]',1,'Besi punya ciri khusus yang berbeda dari kayu atau plastik.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Urutan perubahan wujud es menjadi uap air jika terus dipanaskan adalah...','❄️💧💨','["Padat → Gas → Cair","Padat → Cair → Gas","Gas → Cair → Padat","Cair → Padat → Gas"]',1,'Dimulai dari es yang keras, menjadi air, baru menjadi uap.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Kayu memiliki sifat keras tetapi mudah terbakar. Sifat mudah terbakar merupakan sifat...','🔥🌳','["Sifat fisika","Sifat kimia","Sifat mekanik","Sifat biologis"]',1,'Sifat ini terlihat saat kayu berubah menjadi zat lain seperti abu dan asap.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Sebuah benda bersifat transparan, mudah pecah, keras, dan tidak dapat ditekuk. Benda ini kemungkinan besar adalah...','🪟','["Karet","Plastik","Gelas","Aluminium"]',2,'Hanya satu bahan yang sekaligus transparan, keras, dan mudah pecah.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Energi gerak yang dimiliki mobil yang melaju akan berubah menjadi energi apa saat mobil mengerem?','🚗🛑','["Energi cahaya","Energi panas","Energi listrik","Energi magnet"]',1,'Gesekan rem dengan roda saat mengerem menghasilkan sesuatu yang bisa dirasakan.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_3','Saat air laut dipanaskan matahari, menguap menjadi uap air, naik ke atmosfer, lalu turun kembali sebagai hujan. Proses ini disebut...','🌧️☀️💧','["Siklus pembakaran","Siklus air","Siklus magnetik","Siklus energi panas"]',1,'Proses alami yang melibatkan penguapan, pembentukan awan, dan hujan secara berulang.','medium','');
