INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Apa yang dimaksud dengan atom?','','["Bagian terkecil dari suatu unsur yang masih memiliki sifat kimia unsur tersebut","Zat yang terbuat dari banyak partikel besar","Campuran dua unsur yang mudah dipisahkan","Benda yang bisa dilihat dengan mata telanjang"]',0,'Atom adalah satuan dasar terkecil dari suatu unsur yang masih mempertahankan sifat kimia unsur tersebut.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Manakah di antara berikut yang merupakan contoh unsur?','Fe, O₂, Au','["Besi (Fe), emas (Au), oksigen (O₂)","Air, garam dapur, gula","Plastik, kaca, kayu","Susu, jus jeruk, teh"]',0,'Unsur adalah zat murni yang hanya terdiri dari satu jenis atom.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Air memiliki rumus kimia H₂O. Artinya air adalah...','H₂O','["Senyawa yang terbentuk dari 2 atom hidrogen dan 1 atom oksigen","Unsur yang paling banyak di bumi","Campuran unsur besi dan oksigen","Zat yang selalu berbentuk cair"]',0,'H₂O menunjukkan jumlah dan jenis atom yang bergabung dalam satu molekul air.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Perbedaan utama antara unsur dan senyawa adalah...','','["Unsur terdiri dari satu jenis atom, senyawa terdiri dari dua atau lebih jenis atom yang bergabung","Unsur selalu berwarna, senyawa tidak berwarna","Unsur lebih berat daripada senyawa","Unsur hanya terdapat di alam, senyawa hanya dibuat manusia"]',0,'Lihat jenis atom yang menyusun setiap zat.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Oksigen (O₂) dalam udara yang kita hirup adalah bentuk...','O₂','["Molekul yang terbentuk dari 2 atom oksigen yang bergabung","Unsur oksigen dalam bentuk atom tunggal","Senyawa yang mengandung oksigen dan gas lain","Atom yang terlalu kecil untuk dihitung"]',0,'Lambang O₂ menunjukkan berapa banyak atom oksigen yang bergabung dalam satu molekul.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Besi (Fe) yang digunakan untuk membuat pisau dan paku adalah...','Fe','["Unsur logam yang terbentuk dari atom-atom besi sejenis","Senyawa yang mengandung beberapa jenis atom","Campuran besi dengan air","Hasil perpaduan tiga unsur berbeda"]',0,'Besi murni hanya terdiri dari satu jenis atom.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Ketika dua atau lebih atom bergabung, mereka membentuk...','','["Molekul","Kristal","Gas","Cairan"]',0,'Istilah untuk hasil penggabungan beberapa atom adalah...','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Garam dapur (NaCl) terbentuk dari penggabungan atom natrium (Na) dan klor (Cl). Artinya garam dapur adalah...','NaCl','["Senyawa","Unsur","Elemen langka","Campuran unsur yang mudah dipisahkan"]',0,'Ketika dua unsur berbeda bergabung secara kimia, hasilnya disebut senyawa.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Manakah pernyataan yang BENAR tentang atom?','','["Atom sangat kecil dan tidak bisa dilihat dengan mata telanjang","Atom dapat dilihat jika kita menggunakan lensa pembesar biasa","Semua atom memiliki ukuran dan bentuk yang sama","Atom adalah benda paling besar yang ada di alam"]',0,'Pikirkan tentang ukuran atom dibandingkan dengan benda yang bisa kita lihat.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Emas murni (Au) yang digunakan untuk membuat perhiasan adalah...','Au','["Unsur yang terdiri dari atom-atom emas sejenis","Senyawa yang terbentuk dari emas dan logam lain","Campuran lima unsur berbeda","Atom tunggal yang sangat besar"]',0,'Emas murni hanya terdiri dari satu jenis atom.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Mengapa atom disebut sebagai ''bagian terkecil'' dari suatu unsur?','','["Karena jika atom dipecah lagi, zat tersebut tidak akan memiliki sifat kimia unsur tersebut lagi","Karena atom tidak memiliki massa","Karena atom dapat dilihat dengan mata biasa","Karena atom hanya ada satu di setiap zat"]',0,'Pikirkan apa yang terjadi jika kita terus memecah suatu unsur menjadi bagian yang lebih kecil.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Suatu senyawa selalu memiliki rumus kimia tetap. Contohnya, air selalu H₂O. Ini berarti...','H₂O','["Perbandingan jenis dan jumlah atom dalam air tidak pernah berubah","Air dapat mengandung 2 atau 3 atom hidrogen tergantung sumbernya","Rumus air bisa berbeda di setiap negara","Air tidak memiliki struktur atom yang pasti"]',0,'Senyawa memiliki komposisi atom yang konsisten dan tetap.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Karbon (C) adalah unsur yang terdapat dalam berlian, grafit, dan arang. Hal ini menunjukkan bahwa...','C','["Atom karbon yang sama dapat membentuk benda-benda dengan sifat berbeda","Berlian, grafit, dan arang adalah tiga unsur yang berbeda","Atom karbon hanya ada dalam satu bentuk","Unsur karbon tidak stabil di alam"]',0,'Unsur yang sama (atom yang sama) dapat tersusun dengan cara berbeda dan membentuk sifat yang berbeda.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Manakah yang BUKAN contoh unsur sehari-hari?','','["Air","Tembaga","Oksigen","Perak"]',0,'Air adalah senyawa, bukan unsur. Carilah mana yang bukan zat dari satu jenis atom.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Jika satu molekul air (H₂O) dipecah menjadi atom-atomnya, berapa banyak atom yang akan terbentuk?','H₂O → ?','["3 atom (2 hidrogen + 1 oksigen)","2 atom (hanya hidrogen dan oksigen)","1 atom air yang sangat kecil","5 atom (kombinasi dari semua partikel)"]',0,'H₂O artinya 2 atom hidrogen dan 1 atom oksigen. Jumlahkan semuanya.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Manakah urutan yang BENAR dari yang terkecil hingga terbesar?','','["Atom → Molekul → Zat yang terlihat","Zat yang terlihat → Molekul → Atom","Molekul → Atom → Zat yang terlihat","Atom dan Molekul memiliki ukuran yang sama"]',0,'Pikirkan tingkat kecilnya: atom paling kecil, lalu molekul (kumpulan atom), lalu benda yang bisa dilihat.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Nikel (Ni) digunakan sebagai lapisan pada uang logam dan perhiasan. Nikel adalah...','Ni','["Unsur logam","Senyawa organik","Gas mulia","Hasil pencampuran tiga unsur"]',0,'Nikel adalah satu jenis logam di tabel periodik.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Apa perbedaan antara atom hidrogen tunggal (H) dan molekul hidrogen (H₂)?','H vs H₂','["H adalah satu atom hidrogen, sedangkan H₂ adalah dua atom hidrogen yang bergabung membentuk molekul","H adalah gas, sedangkan H₂ adalah cairan","H adalah atom kecil, sedangkan H₂ adalah atom yang lebih besar","H lebih ringan daripada H₂"]',0,'Angka kecil di belakang simbol menunjukkan jumlah atom dalam molekul.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_4','Jika kita mencampur bubuk besi dengan bubuk sulfur tanpa memanaskannya, campuran ini adalah...','Fe + S','["Campuran dua unsur yang masih bisa dipisahkan","Senyawa besi sulfida yang tidak bisa dipisahkan","Satu unsur baru yang bereaksi dengan dirinya sendiri","Atom yang menyatu secara permanen"]',0,'Jika dua unsur hanya dicampur tapi tidak bereaksi secara kimia, mereka tetap bisa dipisahkan.','hard','');
