INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Planet apa yang paling dekat dengan Matahari?','','["Merkurius","Venus","Bumi","Mars"]',0,'Planet pertama dalam urutan tata surya kami.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Berapa jumlah planet yang mengelilingi Matahari di tata surya kita?','','["6 planet","8 planet","10 planet","12 planet"]',1,'Mulai dari Merkurius sampai Neptunus.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Apa penyebab terjadinya siang dan malam di Bumi?','','["Bumi mengelilingi Matahari","Bumi berputar pada porosnya","Matahari bergerak","Bulan menghalangi Matahari"]',1,'Gerak Bumi yang membuat setengah bagian menghadap Matahari dan setengah lagi menjauh.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Berapa lama Bumi memerlukan waktu untuk mengelilingi Matahari sekali?','','["24 jam","7 hari","1 bulan","1 tahun"]',3,'Ini sama dengan waktu pergantian musim.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Matahari adalah apa dalam tata surya kita?','','["Planet terbesar","Bintang","Satelit alami","Asteroid"]',1,'Benda langit yang sangat panas dan memancarkan cahaya sendiri.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Yang manakah BUKAN fungsi Bulan bagi Bumi?','','["Menerangi malam hari","Mempengaruhi pasang surut laut","Menjaga stabilitas rotasi Bumi","Menghasilkan panas untuk Bumi"]',3,'Bulan adalah satelit alami, bukan penghasil panas.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Galaksi tempat Bumi kita berada bernama apa?','','["Andromeda","Bima Sakti","Segitiga","Centaurus A"]',1,'Nama galaksi kami dalam bahasa Indonesia yang indah.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Apa perbedaan utama antara planet dan bintang?','','["Planet lebih besar daripada bintang","Bintang memancarkan cahaya sendiri, planet hanya memantulkan","Planet bergerak, bintang selalu diam","Tidak ada perbedaan"]',1,'Pikirkan tentang apa yang membuat Matahari berbeda dari Bumi.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Satelit alami Bumi adalah...','','["Matahari","Bulan","Venus","Mars"]',1,'Benda langit yang selalu mengelilingi Bumi dan terlihat di malam hari.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Fase Bulan terjadi karena apa?','','["Bayangan Bumi yang jatuh ke Bulan","Posisi Bulan relatif terhadap Bumi dan Matahari","Bulan bergerak lebih cepat dari Bumi","Cahaya Matahari berkurang"]',1,'Tergantung pada bagian Bulan mana yang mendapat cahaya Matahari dan terlihat dari Bumi.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Urutan planet dari yang terdekat ke terjauh dari Matahari adalah...','','["Merkurius, Venus, Bumi, Mars, Jupiter, Saturnus, Uranus, Neptunus","Venus, Merkurius, Bumi, Mars, Jupiter, Saturnus, Neptunus, Uranus","Bumi, Venus, Merkurius, Mars, Jupiter, Saturnus, Uranus, Neptunus","Mars, Merkurius, Venus, Bumi, Jupiter, Saturnus, Neptunus, Uranus"]',0,'Ingat urutan dengan mnemonik: Merkurius, Venus, Bumi, Mars...','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Apa itu gravitasi dalam konteks angkasa?','','["Gaya yang menarik benda-benda saling mendekati","Cahaya yang dipancarkan bintang","Suara yang terdengar di luar angkasa","Angin yang bertiup di langit"]',0,'Gaya yang membuat Bumi tetap mengelilingi Matahari dan membuat kita tetap berdiri di tanah.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Planet mana yang memiliki cincin yang paling menonjol?','','["Jupiter","Uranus","Saturnus","Mars"]',2,'Planet dengan cincin indah yang terlihat dengan teleskop kecil.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Manakah pernyataan berikut yang SALAH tentang Bumi?','','["Bumi berputar pada porosnya setiap 24 jam","Bumi mengelilingi Matahari setahun sekali","Bumi adalah planet gas raksasa","Bumi memiliki atmosfer yang melindungi"]',2,'Ingat jenisnya; Bumi termasuk planet apa?','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Mengapa ada musim di Bumi?','','["Karena Bumi berputar lebih cepat","Karena kemiringan sumbu Bumi saat mengelilingi Matahari","Karena Matahari bergerak mendekati dan menjauh","Karena Bulan mempengaruhi cuaca"]',1,'Terkait dengan sudut datangnya cahaya Matahari di berbagai belahan Bumi.','medium','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Bintang adalah benda langit yang... (ciri utama)','','["Selalu diam dan tidak bergerak","Hanya terlihat di malam hari","Memancarkan cahaya dan energi sendiri","Mengelilingi planet-planet"]',2,'Ciri yang membedakan bintang dari planet.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Matahari tersusun terutama dari gas apa?','','["Oksigen dan nitrogen","Hidrogen dan helium","Karbon dan uap air","Besi dan belerang"]',1,'Dua gas paling ringan di alam semesta yang menjadi bahan bakar bintang.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Planet manakah yang ukurannya paling besar di tata surya?','','["Saturnus","Jupiter","Venus","Neptunus"]',1,'Planet gas raksasa dengan bintik merah besar yang terkenal.','easy','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Berapa lama satu siklus penuh fase Bulan berlangsung?','','["7 hari","15 hari","Sekitar 29–30 hari","Tepat 365 hari"]',2,'Satu siklus dimulai dari Bulan Baru hingga kembali ke Bulan Baru lagi.','hard','');
INSERT INTO item(zone_id,q,expr,opts_json,a,hint,difficulty,knowledge) VALUES('science_5','Apa yang terjadi ketika Bulan berada di antara Bumi dan Matahari?','','["Terjadi gerhana Bulan","Terjadi gerhana Matahari","Tidak ada yang istimewa terjadi","Fase Bulan Purnama"]',1,'Bayangan apa yang terhalangi?','medium','');
